    font-weight: 500;
}

.sidebar-icon {
    font-size: 1.1rem;
}

.sidebar-label {
    font-size: 0.95rem;
}

@namespace sv_8c399e8d17784ae1b4b6d09e32777490.Components.Pages.Settings
@using sv_8c399e8d17784ae1b4b6d09e32777490.Models

<div class="profile-section">
    <h3>Profile Settings</h3>

    @if (_successMessage is not null)
    {
        <div class="toast-success">@_successMessage</div>
    }

    <div class="avatar-area">
        <div class="avatar-preview">
            @if (!string.IsNullOrWhiteSpace(_avatarUrl))
            {
                <img src="@_avatarUrl" alt="Avatar" />
            }
            else
            {
                <div class="avatar-placeholder">👤</div>
            }
        </div>
        <div class="avatar-url">
            <label>Avatar URL</label>
            <input type="url" @bind="_avatarUrl" placeholder="https://example.com/avatar.png" />
        </div>
    </div>

    <div class="form-group">
        <label>Display Name</label>
        <input type="text" @bind="_displayName" placeholder="Your display name" />
    </div>

    <div class="form-group">
        <label>Email</label>
        <input type="email" @bind="_email" placeholder="you@example.com" />
    </div>

    <div class="form-group">
        <label>Bio</label>
        <textarea @bind="_bio" rows="4" placeholder="Tell us about yourself..."></textarea>
    </div>

    <div class="button-group">
        <button class="btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving..." : "Save Changes")
        </button>
        <button class="btn-secondary" @onclick="Discard">Discard Changes</button>
    </div>
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private bool _saving;
    private string? _successMessage;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !_saving)
        {
            LoadFromProfile(Profile);
        }
    }

    private void LoadFromProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _successMessage = null;

        var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await OnSave.InvokeAsync(updated);

        _successMessage = "Profile saved successfully!";
        _saving = false;

        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        _successMessage = null;
        StateHasChanged();
    }

    private void Discard()
    {
        if (Profile is not null)
        {
            LoadFromProfile(Profile);
        }
        _successMessage = null;
    }
}

.profile-section {
    max-width: 600px;
}

.profile-section h3 {
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

.toast-success {
    background: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
    border-radius: 6px;
    padding: 0.75rem 1rem;
    margin-bottom: 1rem;
    animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-10px); }
    to { opacity: 1; transform: translateY(0); }
}

.avatar-area {
    display: flex;
    align-items: center;
    gap: 1.5rem;
    margin-bottom: 1.5rem;
}

.avatar-preview {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    overflow: hidden;
    background: #e9ecef;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.avatar-preview img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    font-size: 2rem;
}

.avatar-url {
    flex: 1;
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.form-group input,
.form-group textarea,
.avatar-url input {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #d0d0d0;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
}

.form-group input:focus,
.form-group textarea:focus,
.avatar-url input:focus {
    outline: none;
    border-color: #1565c0;
    box-shadow: 0 0 0 3px rgba(21, 101, 192, 0.1);
}

.avatar-url label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn-primary {
    background: #1565c0;
    color: white;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 6px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-primary:hover:not(:disabled) {
    background: #0d47a1;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-secondary {
    background: white;
    color: #555;
    border: 1px solid #d0d0d0;
    padding: 0.6rem 1.5rem;
    border-radius: 6px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-secondary:hover {
    background: #f5f5f5;
    border-color: #bbb;
}

