@namespace sv_8c399e8d17784ae1b4b6d09e32777490.Components.Pages.Settings
@using sv_8c399e8d17784ae1b4b6d09e32777490.Models

<div class="notifications-section">
    <h3>Notification Preferences</h3>

    <div class="toggle-group">
        <div class="toggle-item">
            <label class="toggle-label">
                <span>Email Notifications</span>
                <span class="toggle-description">Receive notifications via email</span>
            </label>
            <label class="switch">
                <input type="checkbox" @bind="_emailNotifications" />
                <span class="slider"></span>
            </label>
        </div>

        <div class="toggle-item">
            <label class="toggle-label">
                <span>Push Notifications</span>
                <span class="toggle-description">Receive browser push notifications</span>
            </label>
            <label class="switch">
                <input type="checkbox" @bind="_pushNotifications" />
                <span class="slider"></span>
            </label>
        </div>

        <div class="toggle-item">
            <label class="toggle-label">
                <span>Weekly Digest</span>
                <span class="toggle-description">Get a weekly summary of activity</span>
            </label>
            <label class="switch">
                <input type="checkbox" @bind="_weeklyDigest" />
                <span class="slider"></span>
            </label>
        </div>
    </div>

    <div class="channels-section">
        <h4>Muted Channels</h4>
        <p class="channels-description">Select channels to mute notifications from:</p>
        <div class="channel-list">
            @foreach (var channel in AvailableChannels)
            {
                <label class="channel-item">
                    <input type="checkbox"
                           checked="@_mutedChannels.Contains(channel)"
                           @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                    <span>@channel</span>
                </label>
            }
        </div>
    </div>

    <button class="btn-primary" @onclick="SaveAsync" disabled="@_saving">
        @(_saving ? "Saving..." : "Save Preferences")
    </button>
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }
    [Parameter] public List<string> AvailableChannels { get; set; } = ["general", "announcements", "dev-team", "design", "marketing", "support"];

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private bool _saving;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_saving)
        {
            _emailNotifications = Prefs.EmailNotifications;
            _pushNotifications = Prefs.PushNotifications;
            _weeklyDigest = Prefs.WeeklyDigest;
            _mutedChannels = new HashSet<string>(Prefs.MutedChannels);
        }
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        _saving = false;
    }
}

.notifications-section {
    max-width: 600px;
}

.notifications-section h3 {
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

.toggle-group {
    margin-bottom: 2rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.toggle-label {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.toggle-label span:first-child {
    font-weight: 500;
    color: #333;
}

.toggle-description {
    font-size: 0.85rem;
    color: #777;
}

.switch {
    position: relative;
    display: inline-block;
    width: 48px;
    height: 26px;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: #ccc;
    transition: 0.3s;
    border-radius: 26px;
}

.slider::before {
    position: absolute;
    content: "";
    height: 20px;
    width: 20px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    transition: 0.3s;
    border-radius: 50%;
}

.switch input:checked + .slider {
    background-color: #1565c0;
}

.switch input:checked + .slider::before {
    transform: translateX(22px);
}

.channels-section {
    margin-bottom: 1.5rem;
}

.channels-section h4 {
    margin-bottom: 0.5rem;
    color: #333;
}

.channels-description {
    font-size: 0.9rem;
    color: #666;
    margin-bottom: 1rem;
}

.channel-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 0.75rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 0.75rem;
    background: #f8f9fa;
    border-radius: 6px;
    cursor: pointer;
    transition: background 0.2s;
}

.channel-item:hover {
    background: #e9ecef;
}

.channel-item input[type="checkbox"] {
    accent-color: #1565c0;
}

.btn-primary {
    background: #1565c0;
    color: white;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 6px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-primary:hover:not(:disabled) {
    background: #0d47a1;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

@namespace sv_8c399e8d17784ae1b4b6d09e32777490.Components.Pages.Settings
@using sv_8c399e8d17784ae1b4b6d09e32777490.Models

<div class="security-section">
    <h3>Security Settings</h3>

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => _passwordExpanded = !_passwordExpanded">
            <span>🔑 Change Password</span>
            <span class="expand-icon">@(_passwordExpanded ? "▾" : "▸")</span>
        </button>
        @if (_passwordExpanded)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label>Current Password</label>
                    <input type="password" @bind="_currentPassword" placeholder="Enter current password" />
                </div>
                <div class="form-group">
                    <label>New Password</label>
                    <input type="password" @bind="_newPassword" placeholder="Enter new password" />
                </div>
                <div class="form-group">
                    <label>Confirm New Password</label>
                    <input type="password" @bind="_confirmPassword" placeholder="Confirm new password" />
                </div>

                @if (_passwordError is not null)
                {
                    <div class="error-message">@_passwordError</div>
                }
                @if (_passwordSuccess)
                {
                    <div class="success-message">Password updated successfully!</div>
                }

                <button class="btn-primary" @onclick="UpdatePasswordAsync" disabled="@_changingPassword">
                    @(_changingPassword ? "Updating..." : "Update Password")
                </button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="twofa-section">
        <div class="twofa-header">
            <div class="twofa-info">
                <h4>Two-Factor Authentication</h4>
                <span class="status-badge @(TwoFactorEnabled ? "status-enabled" : "status-disabled")">
                    @(TwoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            <label class="switch">
                <input type="checkbox" checked="@TwoFactorEnabled" @onchange="OnTwoFactorToggled" />
                <span class="slider"></span>
            </label>
        </div>
        @if (LastPasswordChange.HasValue)
        {
            <p class="last-change">Last password change: @LastPasswordChange.Value.ToString("MMMM d, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <div class="sessions-section">
        <h4>Active Sessions</h4>
        @if (Sessions?.Count > 0)
        {
            <div class="sessions-table-wrapper">
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (session.Id != CurrentSessionId)
                                    {
                                        <button class="btn-revoke" @onclick="() => ConfirmRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        }
        else
        {
            <p class="no-sessions">No active sessions found.</p>
        }
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (_sessionToRevoke is not null)
    {
        <div class="dialog-overlay" @onclick="CancelRevoke">
            <div class="dialog" @onclick:stopPropagation="true">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                <p class="dialog-warning">This will sign out that device immediately.</p>
                <div class="dialog-buttons">
                    <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    <button class="btn-danger" @onclick="RevokeAsync">Revoke Session</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public bool TwoFactorEnabled { get; set; }
    [Parameter] public DateTime? LastPasswordChange { get; set; }
    [Parameter] public List<ActiveSession>? Sessions { get; set; }
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<bool> OnTwoFactorToggle { get; set; }

    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private bool _passwordSuccess;
    private bool _changingPassword;
    private ActiveSession? _sessionToRevoke;

    private async Task UpdatePasswordAsync()
    {
        _passwordError = null;
        _passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "New password is required.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New passwords do not match.";
            return;
        }
        if (_newPassword.Length < 8)
        {
            _passwordError = "Password must be at least 8 characters.";
            return;
        }

        _changingPassword = true;
        try
        {
            await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
            _passwordSuccess = true;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _passwordError = ex.Message;
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task RevokeAsync()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }

    private async Task OnTwoFactorToggled(ChangeEventArgs e)
    {
        var enabled = (bool)(e.Value ?? false);
        await OnTwoFactorToggle.InvokeAsync(enabled);
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalHours < 1) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalDays < 1) return $"{(int)diff.TotalHours}h ago";
        return lastActive.ToString("MMM d, yyyy");
    }
}

