+    padding: 1rem 0;
+    border-bottom: 1px solid #f0f0f0;
+}
+
+.toggle-label {
+    display: flex;
+    flex-direction: column;
+    gap: 0.25rem;
+}
+
+.toggle-label span:first-child {
+    font-weight: 500;
+    color: #333;
+}
+
+.toggle-description {
+    font-size: 0.85rem;
+    color: #777;
+}
+
+.switch {
+    position: relative;
+    display: inline-block;
+    width: 48px;
+    height: 26px;
+}
+
+.switch input {
+    opacity: 0;
+    width: 0;
+    height: 0;
+}
+
+.slider {
+    position: absolute;
+    cursor: pointer;
+    top: 0;
+    left: 0;
+    right: 0;
+    bottom: 0;
+    background-color: #ccc;
+    transition: 0.3s;
+    border-radius: 26px;
+}
+
+.slider::before {
+    position: absolute;
+    content: "";
+    height: 20px;
+    width: 20px;
+    left: 3px;
+    bottom: 3px;
+    background-color: white;
+    transition: 0.3s;
+    border-radius: 50%;
+}
+
+.switch input:checked + .slider {
+    background-color: #1565c0;
+}
+
+.switch input:checked + .slider::before {
+    transform: translateX(22px);
+}
+
+.channels-section {
+    margin-bottom: 1.5rem;
+}
+
+.channels-section h4 {
+    margin-bottom: 0.5rem;
+    color: #333;
+}
+
+.channels-description {
+    font-size: 0.9rem;
+    color: #666;
+    margin-bottom: 1rem;
+}
+
+.channel-list {
+    display: grid;
+    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
+    gap: 0.75rem;
+}
+
+.channel-item {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    padding: 0.5rem 0.75rem;
+    background: #f8f9fa;
+    border-radius: 6px;
+    cursor: pointer;
+    transition: background 0.2s;
+}
+
+.channel-item:hover {
+    background: #e9ecef;
+}
+
+.channel-item input[type="checkbox"] {
+    accent-color: #1565c0;
+}
+
+.btn-primary {
+    background: #1565c0;
+    color: white;
+    border: none;
+    padding: 0.6rem 1.5rem;
+    border-radius: 6px;
+    font-size: 0.95rem;
+    cursor: pointer;
