+                                <td>@FormatLastActive(session.LastActive)</td>
+                                <td>
+                                    @if (session.Id != CurrentSessionId)
+                                    {
+                                        <button class="btn-revoke" @onclick="() => ConfirmRevoke(session)">
+                                            Revoke
+                                        </button>
+                                    }
+                                    else
+                                    {
+                                        <span class="current-badge">Current</span>
+                                    }
+                                </td>
+                            </tr>
+                        }
+                    </tbody>
+                </table>
+            </div>
+        }
+        else
+        {
+            <p class="no-sessions">No active sessions found.</p>
+        }
+    </div>
+
+    <!-- Revoke Confirmation Dialog -->
+    @if (_sessionToRevoke is not null)
+    {
+        <div class="dialog-overlay" @onclick="CancelRevoke">
+            <div class="dialog" @onclick:stopPropagation="true">
+                <h4>Revoke Session</h4>
+                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
+                <p class="dialog-warning">This will sign out that device immediately.</p>
+                <div class="dialog-buttons">
+                    <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
+                    <button class="btn-danger" @onclick="RevokeAsync">Revoke Session</button>
+                </div>
+            </div>
+        </div>
+    }
+</div>
+
+@code {
+    [Parameter] public bool TwoFactorEnabled { get; set; }
+    [Parameter] public DateTime? LastPasswordChange { get; set; }
+    [Parameter] public List<ActiveSession>? Sessions { get; set; }
+    [Parameter] public string CurrentSessionId { get; set; } = "";
+    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
+    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }
+    [Parameter] public EventCallback<bool> OnTwoFactorToggle { get; set; }
+
+    private bool _passwordExpanded;
+    private string _currentPassword = "";
+    private string _newPassword = "";
+    private string _confirmPassword = "";
+    private string? _passwordError;
+    private bool _passwordSuccess;
+    private bool _changingPassword;
+    private ActiveSession? _sessionToRevoke;
+
+    private async Task UpdatePasswordAsync()
+    {
+        _passwordError = null;
+        _passwordSuccess = false;
+
+        if (string.IsNullOrWhiteSpace(_currentPassword))
+        {
+            _passwordError = "Current password is required.";
+            return;
+        }
+        if (string.IsNullOrWhiteSpace(_newPassword))
+        {
+            _passwordError = "New password is required.";
+            return;
+        }
+        if (_newPassword != _confirmPassword)
+        {
+            _passwordError = "New passwords do not match.";
+            return;
+        }
+        if (_newPassword.Length < 8)
+        {
+            _passwordError = "Password must be at least 8 characters.";
+            return;
+        }
+
+        _changingPassword = true;
+        try
+        {
+            await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
+            _passwordSuccess = true;
+            _currentPassword = "";
+            _newPassword = "";
+            _confirmPassword = "";
+        }
+        catch (Exception ex)
+        {
+            _passwordError = ex.Message;
+        }
+        finally
+        {
+            _changingPassword = false;
+        }
+    }
+
+    private void ConfirmRevoke(ActiveSession session)
+    {
+        _sessionToRevoke = session;
+    }
+
+    private void CancelRevoke()
+    {
+        _sessionToRevoke = null;
+    }
+
+    private async Task RevokeAsync()
+    {
+        if (_sessionToRevoke is not null)
+        {
+            await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
+            _sessionToRevoke = null;
+        }
+    }
+
+    private async Task OnTwoFactorToggled(ChangeEventArgs e)
+    {
+        var enabled = (bool)(e.Value ?? false);
+        await OnTwoFactorToggle.InvokeAsync(enabled);
+    }
+
+    private static string FormatLastActive(DateTime lastActive)
+    {
+        var diff = DateTime.UtcNow - lastActive;
+        if (diff.TotalMinutes < 1) return "Just now";
+        if (diff.TotalHours < 1) return $"{(int)diff.TotalMinutes}m ago";
+        if (diff.TotalDays < 1) return $"{(int)diff.TotalHours}h ago";
+        return lastActive.ToString("MMM d, yyyy");
+    }
+}
