@namespace sv_8c399e8d17784ae1b4b6d09e32777490.Components.Pages.Settings
@using sv_8c399e8d17784ae1b4b6d09e32777490.Models

<div class="appearance-section">
    <h3>Appearance Settings</h3>

    <!-- Theme Selector -->
    <div class="setting-group">
        <h4>Theme</h4>
        <div class="radio-group">
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <label class="radio-item @(_theme == theme ? "selected" : "")">
                    <input type="radio" name="theme" value="@theme"
                           checked="@(_theme == theme)"
                           @onchange="() => _theme = theme" />
                    <span class="radio-icon">@GetThemeIcon(theme)</span>
                    <span>@theme</span>
                </label>
            }
        </div>
    </div>

    <!-- Font Size Selector -->
    <div class="setting-group">
        <h4>Font Size</h4>
        <div class="radio-group">
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <label class="radio-item @(_fontSize == size ? "selected" : "")">
                    <input type="radio" name="fontSize" value="@size"
                           checked="@(_fontSize == size)"
                           @onchange="() => _fontSize = size" />
                    <span class="size-sample" style="font-size: @GetFontSizeValue(size)">Aa</span>
                    <span>@size</span>
                </label>
            }
        </div>
    </div>

    <!-- Language Dropdown -->
    <div class="setting-group">
        <h4>Language</h4>
        <select class="language-select" @bind="_language">
            <option value="en">English</option>
            <option value="es">Español</option>
            <option value="fr">Français</option>
            <option value="de">Deutsch</option>
            <option value="ja">日本語</option>
            <option value="zh">中文</option>
            <option value="pt">Português</option>
        </select>
    </div>

    <!-- Compact Mode -->
    <div class="setting-group">
        <div class="compact-toggle">
            <div>
                <h4>Compact Mode</h4>
                <p class="toggle-description">Reduce spacing and padding for a denser layout</p>
            </div>
            <label class="switch">
                <input type="checkbox" @bind="_compactMode" />
                <span class="slider"></span>
            </label>
        </div>
    </div>

    <!-- Live Preview -->
    <div class="setting-group">
        <h4>Preview</h4>
        <div class="preview-area @GetPreviewClasses()">
            <div class="preview-header">
                <span class="preview-title">Sample Content</span>
                <span class="preview-badge">Preview</span>
            </div>
            <p class="preview-text">
                This is how your content will look with the selected appearance settings.
                The theme, font size, and compact mode are reflected here.
            </p>
            <div class="preview-actions">
                <button class="preview-btn-primary">Primary Action</button>
                <button class="preview-btn-secondary">Secondary</button>
            </div>
        </div>
    </div>

    <button class="btn-primary" @onclick="SaveAsync" disabled="@_saving">
        @(_saving ? "Saving..." : "Save")
    </button>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _saving;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_saving)
        {
            _theme = Settings.Theme;
            _fontSize = Settings.FontSize;
            _language = Settings.Language;
            _compactMode = Settings.CompactMode;
        }
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(updated);
        _saving = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_theme.ToLowerInvariant()} preview-font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " preview-compact";
        return classes;
    }

    private static string GetThemeIcon(string theme) => theme switch
    {
        "Light" => "☀️",
        "Dark" => "🌙",
        "System" => "💻",
        _ => "⚙️"
    };

    private static string GetFontSizeValue(string size) => size switch
    {
        "Small" => "0.8rem",
        "Medium" => "1rem",
        "Large" => "1.2rem",
        _ => "1rem"
    };
}

.appearance-section {
    max-width: 600px;
}

.appearance-section h3 {
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

.setting-group {
    margin-bottom: 1.75rem;
}

.setting-group h4 {
    margin-bottom: 0.75rem;
    color: #333;
    font-size: 0.95rem;
}

.radio-group {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.75rem 1.25rem;
    border: 2px solid #e0e0e0;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.2s;
    min-width: 120px;
}

.radio-item:hover {
    border-color: #90caf9;
}

.radio-item.selected {
    border-color: #1565c0;
    background: #e3f2fd;
}

.radio-item input[type="radio"] {
    display: none;
}

.radio-icon {
    font-size: 1.2rem;
}

.size-sample {
    font-weight: 600;
    color: #555;
    width: 2rem;
    text-align: center;
}

.language-select {
    width: 100%;
    max-width: 300px;
    padding: 0.6rem 0.8rem;
    border: 1px solid #d0d0d0;
    border-radius: 6px;
    font-size: 0.95rem;
    background: white;
    cursor: pointer;
}

.language-select:focus {
    outline: none;
    border-color: #1565c0;
    box-shadow: 0 0 0 3px rgba(21, 101, 192, 0.1);
}

.compact-toggle {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.compact-toggle h4 {
    margin-bottom: 0.25rem;
}

.toggle-description {
    font-size: 0.85rem;
    color: #666;
    margin: 0;
}

.switch {
    position: relative;
    display: inline-block;
    width: 48px;
    height: 26px;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: #ccc;
    transition: 0.3s;
    border-radius: 26px;
}

.slider::before {
    position: absolute;
    content: "";
    height: 20px;
    width: 20px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    transition: 0.3s;
    border-radius: 50%;
}

.switch input:checked + .slider {
    background-color: #1565c0;
}

.switch input:checked + .slider::before {
    transform: translateX(22px);
}

/* Live Preview */
.preview-area {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.5rem;
    transition: all 0.3s;
}

.preview-area.preview-theme-light {
    background: #ffffff;
    color: #333;
}

.preview-area.preview-theme-dark {
    background: #1a1a2e;
    color: #e0e0e0;
    border-color: #333;
}

.preview-area.preview-theme-system {
    background: #f8f9fa;
    color: #333;
}

.preview-area.preview-font-small {
    font-size: 0.85rem;
}

.preview-area.preview-font-medium {
    font-size: 1rem;
}

.preview-area.preview-font-large {
    font-size: 1.15rem;
}

.preview-area.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 0.75rem;
}

.preview-title {
    font-weight: 600;
    font-size: 1.1em;
}

.preview-badge {
    background: #e3f2fd;
    color: #1565c0;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75em;
}

.preview-theme-dark .preview-badge {
    background: #1e3a5f;
    color: #90caf9;
}

.preview-text {
    margin-bottom: 1rem;
    line-height: 1.6;
}

.preview-actions {
    display: flex;
    gap: 0.5rem;
}

.preview-btn-primary {
    background: #1565c0;
    color: white;
    border: none;
    padding: 0.4rem 1rem;
    border-radius: 4px;
    font-size: 0.9em;
    cursor: default;
}

.preview-btn-secondary {
    background: transparent;
    color: inherit;
    border: 1px solid currentColor;
    padding: 0.4rem 1rem;
    border-radius: 4px;
    font-size: 0.9em;
    cursor: default;
    opacity: 0.7;
}

.btn-primary {
    background: #1565c0;
    color: white;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 6px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-primary:hover:not(:disabled) {
    background: #0d47a1;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

