    background: #f8f9fa;
    color: #333;
}

.preview-area.preview-font-small {
    font-size: 0.85rem;
}

.preview-area.preview-font-medium {
    font-size: 1rem;
}

.preview-area.preview-font-large {
    font-size: 1.15rem;
}

.preview-area.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

