    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 0.75rem;
}

.preview-title {
    font-weight: 600;
    font-size: 1.1em;
}

.preview-badge {
    background: #e3f2fd;
    color: #1565c0;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75em;
}

.preview-theme-dark .preview-badge {
    background: #1e3a5f;
    color: #90caf9;
}

.preview-text {
    margin-bottom: 1rem;
