}

.preview-actions {
    display: flex;
    gap: 0.5rem;
}

.preview-btn-primary {
    background: #1565c0;
    color: white;
    border: none;
    padding: 0.4rem 1rem;
    border-radius: 4px;
    font-size: 0.9em;
    cursor: default;
}

.preview-btn-secondary {
    background: transparent;
    color: inherit;
    border: 1px solid currentColor;
    padding: 0.4rem 1rem;
    border-radius: 4px;
    font-size: 0.9em;
    cursor: default;
    opacity: 0.7;
}

.btn-primary {
    background: #1565c0;
    color: white;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 6px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-primary:hover:not(:disabled) {
    background: #0d47a1;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}
