@page "/settings"
@namespace sv_8c399e8d17784ae1b4b6d09e32777490.Components.Pages.Settings
@using sv_8c399e8d17784ae1b4b6d09e32777490.Models
@using sv_8c399e8d17784ae1b4b6d09e32777490.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionSelected="section => _activeSection = section" />

    <main class="settings-content">
        @if (_loading)
        {
            <div class="loading-state">
                <span class="loading-spinner"></span>
                <span>Loading settings...</span>
            </div>
        }
        else
        {
            @switch (_activeSection)
            {
                case "Profile":
                    <ProfileSection Profile="@_profile" OnSave="SaveProfileAsync" />
                    break;
                case "Notifications":
                    <NotificationsSection Prefs="@_notificationPrefs" OnSave="SaveNotificationsAsync" />
                    break;
                case "Security":
                    <SecuritySection TwoFactorEnabled="@(_security?.TwoFactorEnabled ?? false)"
                                     LastPasswordChange="@_security?.LastPasswordChange"
                                     Sessions="@_security?.Sessions"
                                     CurrentSessionId="@_currentSessionId"
                                     OnRevokeSession="RevokeSessionAsync"
                                     OnChangePassword="ChangePasswordAsync"
                                     OnTwoFactorToggle="ToggleTwoFactorAsync" />
                    break;
                case "Appearance":
                    <AppearanceSection Settings="@_appearance" OnSave="SaveAppearanceAsync" />
                    break;
            }
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";
    private bool _loading = true;

    private UserProfile? _profile;
    private NotificationPrefs? _notificationPrefs;
    private SecuritySettings? _security;
    private AppearanceSettings? _appearance;
    private string _currentSessionId = "";

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettingsAsync();
        _loading = false;
    }

    private async Task LoadAllSettingsAsync()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notificationsTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notificationsTask, securityTask, appearanceTask);

        _profile = await profileTask;
        _notificationPrefs = await notificationsTask;
        _security = await securityTask;
        _appearance = await appearanceTask;

        // Assume first session is current
        if (_security?.Sessions.Count > 0)
        {
            _currentSessionId = _security.Sessions[0].Id;
        }
    }

    private async Task SaveProfileAsync(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        _profile = profile;
    }

    private async Task SaveNotificationsAsync(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
    }

    private async Task ChangePasswordAsync((string currentPassword, string newPassword) args)
    {
        await SettingsService.ChangePasswordAsync(args.currentPassword, args.newPassword);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task ToggleTwoFactorAsync(bool enabled)
    {
        // Reload security settings to reflect the change
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        _appearance = settings;
    }
}

.settings-layout {
    display: flex;
    height: calc(100vh - 60px);
    background: white;
}

.settings-content {
    flex: 1;
    padding: 2rem 3rem;
    overflow-y: auto;
}

.loading-state {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 2rem;
    color: #666;
}

.loading-spinner {
    display: inline-block;
    width: 20px;
    height: 20px;
    border: 2px solid #e0e0e0;
    border-top-color: #1565c0;
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

